import{_ as t,o,c as r,a3 as a}from"./chunks/framework.DEy3KOfk.js";const h=JSON.parse('{"title":"Troubleshoot port forwarding","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/upnpumpkin/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/upnpumpkin/docs/troubleshooting.md","filePath":"packages/upnpumpkin/docs/troubleshooting.md","lastUpdated":1791428389000}'),s={name:"packages/upnpumpkin/docs/troubleshooting.md"};function n(i,e,p,d,u,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshoot-port-forwarding" tabindex="-1">Troubleshoot port forwarding <a class="header-anchor" href="#troubleshoot-port-forwarding" aria-label="Permalink to &quot;Troubleshoot port forwarding&quot;">​</a></h1><h2 id="no-router-is-found" tabindex="-1">No router is found <a class="header-anchor" href="#no-router-is-found" aria-label="Permalink to &quot;No router is found&quot;">​</a></h2><p>Confirm UPnP or NAT-PMP is enabled in the router settings and that the server host shares the router&#39;s local network. If multicast discovery is blocked, set <code>router.upnp_search</code> to the router&#39;s address and port. For NAT-PMP, set <code>router.nat_pmp_gateway</code> to the gateway address when automatic local-address probing cannot find it.</p><p>Containers and networks with multiple routers can hide the gateway. Ensure the container has the network access required to send and receive router discovery packets.</p><h2 id="a-mapping-is-refused-or-players-cannot-connect" tabindex="-1">A mapping is refused or players cannot connect <a class="header-anchor" href="#a-mapping-is-refused-or-players-cannot-connect" aria-label="Permalink to &quot;A mapping is refused or players cannot connect&quot;">​</a></h2><p>Check <code>/upnp status</code> for the router address and each port&#39;s state. A router with a non-public internet-side address, including carrier-grade NAT, cannot provide an inbound route. A machine that already has a public address does not need a mapping. Some routers are deliberately refused because they do not support UPnP or NAT-PMP safely; create the port rules manually in that case.</p><p>Confirm the Java and Bedrock configured ports match the listeners and protocols. Java uses TCP; Bedrock uses UDP. The router&#39;s mapping does not replace host firewall rules.</p><h2 id="a-plugin-s-requested-port-closes" tabindex="-1">A plugin&#39;s requested port closes <a class="header-anchor" href="#a-plugin-s-requested-port-closes" aria-label="Permalink to &quot;A plugin&#39;s requested port closes&quot;">​</a></h2><p>Check that <code>plugins.allow_requests</code> is enabled and that the requesting plugin stays active. Each plugin can keep at most <code>plugins.max_requests_per_plugin</code> mappings open. Requests expire after five minutes without a refresh and close when the requesting plugin stops its watcher or the server stops.</p><p>Use <code>/upnp reload</code> after editing the config. If the plugin reports that its router is unsupported, no mapping was opened; forward the port manually instead.</p>',10)])])}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
